package id.pengadegan.pegawai;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.*;import android.location.Location;import com.google.android.gms.location.*;import org.json.*;import java.net.*;import java.io.*;import java.util.*;
public class TrackingService extends Service {
 HandlerThread thread;Handler worker;FusedLocationProviderClient fused;PointQueue queue;volatile String token="";static volatile boolean running=false;volatile boolean foreground=false;volatile long sessionId=0;long lastAcceptedElapsed=0;Location previous;LocationCallback callback;
 public void onCreate(){super.onCreate();((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(new NotificationChannel("tracking","Lokasi selama bertugas",NotificationManager.IMPORTANCE_LOW));promote();queue=new PointQueue(this);thread=new HandlerThread("PengadeganUpload");thread.start();worker=new Handler(thread.getLooper());fused=LocationServices.getFusedLocationProviderClient(this);callback=new LocationCallback(){public void onLocationResult(LocationResult result){for(Location l:result.getLocations())capture(l);}};}
 Notification notification(String text){PendingIntent pi=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);return new Notification.Builder(this,"tracking").setSmallIcon(R.drawable.ic_location).setContentTitle("Pengadegan · Tracking presisi").setContentText(text).setContentIntent(pi).setOngoing(true).build();}
 void promote(){if(Build.VERSION.SDK_INT>=29)startForeground(44,notification("Menyiapkan GPS"),ServiceInfo.FOREGROUND_SERVICE_TYPE_LOCATION);else startForeground(44,notification("Menyiapkan GPS"));foreground=true;}
 void notice(String s){if(!running||!foreground)return;try{((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(44,notification(s));}catch(Exception ignored){}}
 public int onStartCommand(Intent i,int flags,int id){if(i!=null&&"FLUSH".equals(i.getAction())&&running){sessionId=0;worker.removeCallbacks(tick);worker.post(tick);return START_NOT_STICKY;}if(!foreground)promote();if(checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){stopSelf();return START_NOT_STICKY;}String saved=TokenStore.read(this);if(saved.isEmpty()){stopSelf();return START_NOT_STICKY;}if(!saved.equals(token))sessionId=0;token=saved;if(!running){running=true;LocationRequest request=new LocationRequest.Builder(Priority.PRIORITY_HIGH_ACCURACY,5000).setMinUpdateIntervalMillis(3000).setMaxUpdateDelayMillis(5000).setWaitForAccurateLocation(true).build();try{fused.requestLocationUpdates(request,callback,Looper.getMainLooper()).addOnFailureListener(e->notice("GPS gagal. Periksa Lokasi akurat dan Google Play services."));}catch(SecurityException e){stopSelf();return START_NOT_STICKY;}worker.post(tick);}return START_STICKY;}
 void capture(Location l){if(!running||sessionId<=0)return;long now=SystemClock.elapsedRealtimeNanos(),age=now-l.getElapsedRealtimeNanos();if(age<0||age>15000000000L||!l.hasAccuracy()||l.getAccuracy()>100){notice("GPS kurang akurat. Menunggu titik baru.");return;}long elapsed=l.getElapsedRealtimeNanos()/1000000L;boolean moving=(l.hasSpeed()&&l.getSpeed()>.5f)||(previous!=null&&l.distanceTo(previous)>Math.max(8,l.getAccuracy()));long interval=moving?5000:15000;if(lastAcceptedElapsed>0&&elapsed-lastAcceptedElapsed<interval)return;if(previous!=null){float delta=l.distanceTo(previous);double seconds=(l.getElapsedRealtimeNanos()-previous.getElapsedRealtimeNanos())/1e9;if(seconds>0&&delta>60*seconds+l.getAccuracy()+previous.getAccuracy()){notice("Lonjakan GPS disaring. Menunggu posisi stabil.");return;}}try{JSONObject p=new JSONObject().put("id",UUID.randomUUID().toString()).put("session_id",sessionId).put("lat",l.getLatitude()).put("lng",l.getLongitude()).put("acc",l.getAccuracy()).put("fix_epoch",l.getTime()/1000).put("speed",l.hasSpeed()?l.getSpeed():0);if(!queue.add(p)){notice("Antrean penuh. Sambungkan internet untuk mengirim GPS.");return;}previous=new Location(l);lastAcceptedElapsed=elapsed;}catch(Exception e){notice("Titik GPS belum tersimpan di perangkat.");}}
 JSONObject api(String endpoint,JSONObject body)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(AppConfig.BASE+"/api/mobile/"+endpoint+".php").openConnection();c.setConnectTimeout(6000);c.setReadTimeout(6000);c.setInstanceFollowRedirects(false);c.setRequestProperty("Authorization","Bearer "+token);try{if(body!=null){c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream out=c.getOutputStream()){out.write(body.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}}int code=c.getResponseCode();if(code==401||code==403){TokenStore.clear(this);stopSelf();throw new IOException("Sesi akun berakhir");}if(code!=200)throw new IOException("Server belum menerima lokasi");try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);JSONObject j=new JSONObject(out.toString("UTF-8"));if(!j.optBoolean("ok"))throw new IOException("Respons server belum berhasil");return j;}}finally{c.disconnect();}}
 final Runnable tick=new Runnable(){public void run(){if(!running)return;try{JSONObject status=api("status",null);long uid=status.optLong("uid");if(uid<=0)throw new IOException("Server perlu patch V9");queue.owner(String.valueOf(uid));JSONObject s=status.optJSONObject("session");long newId=status.optBoolean("active")&&s!=null?s.optLong("id"):0;if(newId!=sessionId){sessionId=newId;new Handler(Looper.getMainLooper()).post(()->{previous=null;lastAcceptedElapsed=0;});}JSONArray batch=queue.batch();if(batch.length()>0){JSONObject result=api("points_batch",new JSONObject().put("points",batch));JSONArray ack=result.optJSONArray("ack");if(ack==null)throw new IOException("Server belum mengakui titik GPS");queue.ack(ack);JSONObject rejected=result.optJSONObject("rejected");int discarded=rejected==null?0:rejected.length();notice((discarded>0?discarded+" titik buruk ditolak · ":"")+"GPS terkirim · antrean "+queue.size()+" · "+new java.text.SimpleDateFormat("HH:mm:ss",Locale.US).format(new Date()));}else notice(sessionId>0?"GPS aktif · menunggu titik presisi":"Sesi kerja selesai");if(newId==0&&queue.size()==0){stopSelf();return;}}catch(Exception e){if(running)notice("Internet/server terputus · "+queue.size()+" titik menunggu");}if(running)worker.postDelayed(this,5000);}};
 public IBinder onBind(Intent i){return null;}
 public void onDestroy(){running=false;sessionId=0;if(worker!=null)worker.removeCallbacksAndMessages(null);if(fused!=null&&callback!=null)fused.removeLocationUpdates(callback);if(worker!=null&&queue!=null)worker.post(()->queue.close());if(thread!=null)thread.quitSafely();foreground=false;stopForeground(true);super.onDestroy();}
}
